import{_ as o,o as a,c as r,a5 as d}from"./chunks/framework.BmD0ICqc.js";const t="/study/images/browser/audio-gain-timeline.svg",i="/study/images/browser/audio-fade-waveform.svg",g=JSON.parse('{"title":"Web Audioのゲインオートメーション — フェードとクリックノイズ","description":"","frontmatter":{"title":"Web Audioのゲインオートメーション — フェードとクリックノイズ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"ゲインの切り替えとフェードを音声の時間軸で予約し、同じ音を止めたときの波形の段差を比べる。","aliases":["Web Audio API","AudioParam","GainNode","setValueAtTime","linearRampToValueAtTime","a-rate","k-rate","フェード","クリックノイズ"],"verification":"W3C Web Audio APIのAudioParam・GainNode・BaseAudioContext・OfflineAudioContextに照合（2026-11-06）"}},"headers":[],"relativePath":"browser/audio-gain-automation.md","filePath":"browser/audio-gain-automation.md"}'),c={name:"browser/audio-gain-automation.md"};function n(s,e,u,l,m,f){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="web-audioのゲインオートメーション-—-フェードとクリックノイズ" tabindex="-1">Web Audioのゲインオートメーション — フェードとクリックノイズ <a class="header-anchor" href="#web-audioのゲインオートメーション-—-フェードとクリックノイズ" aria-label="Permalink to &quot;Web Audioのゲインオートメーション — フェードとクリックノイズ&quot;">​</a></h1><p>ゲームで再生中の効果音を消すとき、波形が大きく振れている途中で音を切ると、切った位置に段差ができます。この急な変化が短いクリック音として聞こえることがあります。音の終わりを数ミリ秒かけて小さくするフェードアウトでは、波形の振れ幅がゼロに近づいてから無音になります。</p><h2 id="音声の時間軸でゲインを予約する" tabindex="-1">音声の時間軸でゲインを予約する <a class="header-anchor" href="#音声の時間軸でゲインを予約する" aria-label="Permalink to &quot;音声の時間軸でゲインを予約する&quot;">​</a></h2><p>フレーム <code>n</code> の入力を <code>x[n]</code>、そのときのゲインを <code>g[n]</code> とすると、 <code>GainNode</code> の出力は <code>y[n] = x[n] × g[n]</code> です。音を足し合わせるときに固定の倍率を使ったのと同じ掛け算を、ここではフレームごとに変わる倍率で行います。<a href="/study/browser/audio-mixing-and-headroom.html">Web Audioのミキシング</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#GainNode" target="_blank" rel="noreferrer">W3C Web Audio APIのGainNode</a></p><p><code>GainNode.gain</code> は <code>AudioParam</code> です。 <code>setValueAtTime(value, time)</code> は指定時刻に値を設定するイベントを追加します。 <code>linearRampToValueAtTime(value, endTime)</code> は直前のイベントから指定の終点まで、値を時間に比例して変化させます。値を保つ区間の後でフェードを始めるには、フェード開始時刻にも <code>setValueAtTime()</code> で開始値を置きます。<a href="https://www.w3.org/TR/webaudio-1.1/#AudioParam" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioParam</a></p><p>予約時刻は <code>BaseAudioContext.currentTime</code> と同じ、コンテキストの開始から数える秒単位です。 <code>AudioParam</code> のイベントは音声グラフのレンダリング時に評価されます。JavaScript の <code>setTimeout()</code> は指定した待ち時間の後にコールバックを実行できるようにします。実際の呼び出し時刻は、イベントループの進み方にもよります。<a href="https://www.w3.org/TR/webaudio-1.1/#dom-baseaudiocontext-currenttime" target="_blank" rel="noreferrer">W3C Web Audio APIのcurrentTime</a>、<a href="https://html.spec.whatwg.org/multipage/timers-and-user-prompts.html#timers" target="_blank" rel="noreferrer">WHATWG HTMLのタイマー</a></p><h2 id="_250-ms-でゲインを変える" tabindex="-1">250 ms でゲインを変える <a class="header-anchor" href="#_250-ms-でゲインを変える" aria-label="Permalink to &quot;250 ms でゲインを変える&quot;">​</a></h2><p>実践では、48,000 Hzのモノラル音源に、ピーク振幅が <code>0.40</code> の400 Hzの余弦波を使います。再生開始側の変化をそろえるため、両方のゲインを最初の10 msで <code>0</code> から <code>1</code> に上げます。250 msになったら、次の二通りで下げます。</p><ul><li><strong>一度に下げる</strong>。 <code>setValueAtTime(0, 0.25)</code> で250 msにゲインを <code>0</code> にします。</li><li><strong>10 ms かけて下げる</strong>。 <code>setValueAtTime(1, 0.25)</code> で250 msのゲインを <code>1</code> に置き、 <code>linearRampToValueAtTime(0, 0.26)</code> で260 msに <code>0</code> へ到達させます。</li></ul><figure class="study-figure"><img src="'+t+'" alt="同じ立ち上がりを持つ二つのゲインを比較する。上段は250ミリ秒で1から0へ切り替わる。下段は250ミリ秒で1を保ち、260ミリ秒までに直線で0へ下がる。" width="760" height="930" loading="lazy"><figcaption>同じ開始時刻に、一方は段差を作り、もう一方は直線で変化します。<a href="/study/images/browser/audio-gain-timeline.svg" target="_blank" rel="noopener noreferrer">ゲインの時間軸を拡大</a></figcaption></figure><h2 id="出力波形の段差を読む" tabindex="-1">出力波形の段差を読む <a class="header-anchor" href="#出力波形の段差を読む" aria-label="Permalink to &quot;出力波形の段差を読む&quot;">​</a></h2><p>フレーム番号を <code>0</code> から数えると、250 msはフレーム <code>12,000</code> です。400 Hzの波形はここでちょうど100周期を終え、振幅が <code>0.40</code> の山に来ます。1つ手前のフレーム <code>11,999</code> は約 <code>0.399452</code> です。ゲインを一度にゼロにすると、出力は次のフレームで <code>0</code> に飛びます。フェードでは開始点のゲインが <code>1</code> なので、そのフレームは <code>0.40</code> 付近を保ち、次のフレームからゲインが下がります。この境界の振幅差の絶対値は、それぞれ約 <code>0.399452</code> と <code>0.000548</code> です。10 msは480フレーム分の時間に当たります。</p><figure class="study-figure"><img src="'+i+'" alt="245から265ミリ秒の出力波形を同じ振幅目盛で比較する。上段は250ミリ秒の波形の山からゼロに切り替わる。下段は250ミリ秒から山と谷が小さくなり、260ミリ秒でゼロに達する。" width="760" height="960" loading="lazy"><figcaption>切り替え前の振幅が大きいほど、ゼロへ落としたときの段差が大きくなります。<a href="/study/images/browser/audio-fade-waveform.svg" target="_blank" rel="noopener noreferrer">出力波形の比較を拡大</a></figcaption></figure><p>フェードが長いほど同じゲイン差を小さな刻みに分けられ、そのぶん消え切る時刻は後ろへ移ります。ゲームでは、消音が完了してから音源を取り外す設計なら、演出で必要な停止の時刻とフェードの長さを一緒に決められます。</p><h2 id="フレーム単位のパラメーターと実践" tabindex="-1">フレーム単位のパラメーターと実践 <a class="header-anchor" href="#フレーム単位のパラメーターと実践" aria-label="Permalink to &quot;フレーム単位のパラメーターと実践&quot;">​</a></h2><p><code>GainNode.gain</code> の既定のオートメーションレートは <code>a-rate</code> です。この設定ではパラメーターをフレームごとに評価します。 <code>k-rate</code> ではレンダリングブロック先頭のフレームで評価し、その値をブロック全体に使います。<a href="https://www.w3.org/TR/webaudio-1.1/#AudioParam" target="_blank" rel="noreferrer">W3C Web Audio APIのAudioParam</a>、<a href="https://www.w3.org/TR/webaudio-1.1/#GainNode" target="_blank" rel="noreferrer">GainNode</a></p><p>実践では <code>OfflineAudioContext</code> を使い、両方の処理結果を <code>AudioBuffer</code> に出力します。境界の前後1フレームの振幅とその差は、このデジタル信号から求めた値です。試聴で聞こえる音の大きさは、再生ゲインや再生装置によっても変わります。<a href="https://www.w3.org/TR/webaudio-1.1/#OfflineAudioContext" target="_blank" rel="noreferrer">W3C Web Audio APIのOfflineAudioContext</a>、<a href="/study/practice/browser/audio-fade-observation.html">ゲインとフェードの実践</a></p><p>一方の音を下げながら別の音を上げると、重なる区間の振幅は二つの波形とゲインで決まります。<a href="/study/browser/audio-crossfade.html">Web Audioのクロスフェード</a>で、途中の実効値がへこむ場合と膨らむ場合を比べられます。</p>',18)])])}const p=o(c,[["render",n]]);export{g as __pageData,p as default};
